\n// path: test/fitur/event/model/event_model_test.dart\nimport 'package:flutter_test/flutter_test.dart';\nimport 'package:wifi/fitur/event/model/event_model.dart';\nimport 'package:wifi/shared/constant/nama_kolom.dart';\n\nvoid main() {\n  group('EventModel', () {\n    final now = DateTime.now();\n    final event = EventModel(\n      id: '1',\n      linkGambar: 'image.png',\n      statusAktif: true,\n      tanggalDibuat: now,\n      tanggalMulai: now.add(const Duration(days: 1)),\n      tanggalBerakhir: now.add(const Duration(days: 2)),\n      diperbaruiPada: now,\n    );\n\n    test('01. fromSqlite harus membuat instance EventModel yang benar', () {\n      final map = {\n        NamaKolom.id: '1',\n        NamaKolom.linkGambar: 'image.png',\n        NamaKolom.statusAktif: 1,\n        NamaKolom.tanggalDibuat: now.millisecondsSinceEpoch,\n        NamaKolom.tanggalMulai: now.add(const Duration(days: 1)).millisecondsSinceEpoch,\n        NamaKolom.tangglberakhir: now.add(const Duration(days: 2)).millisecondsSinceEpoch,\n        NamaKolom.diperbaruiPada: now.millisecondsSinceEpoch,\n      };\n\n      final fromDb = EventModel.fromSqlite(map);\n      expect(fromDb.id, event.id);\n      expect(fromDb.linkGambar, event.linkGambar);\n      expect(fromDb.statusAktif, event.statusAktif);\n      // Membandingkan hanya tahun, bulan, dan hari karena presisi waktu bisa berbeda\n      expect(fromDb.tanggalDibuat.year, event.tanggalDibuat.year);\n      expect(fromDb.tanggalDibuat.month, event.tanggalDibuat.month);\n      expect(fromDb.tanggalDibuat.day, event.tanggalDibuat.day);\n    });\n\n    test('02. toSqlite harus menghasilkan map yang benar', () {\n      final map = event.toSqlite();\n\n      expect(map[NamaKolom.id], '1');\n      expect(map[NamaKolom.linkGambar], 'image.png');\n      expect(map[NamaKolom.statusAktif], 1);\n    });\n\n    test('03. fromSupabase harus membuat instance EventModel yang benar', () {\n      final data = {\n        NamaKolom.linkGambar: 'image.png',\n        NamaKolom.statusAktif: true,\n        NamaKolom.tanggalDibuat: now.toIso8601String(),\n        NamaKolom.tanggalMulai: now.add(const Duration(days: 1)).toIso8601String(),\n        NamaKolom.tangglberakhir: now.add(const Duration(days: 2)).toIso8601String(),\n        NamaKolom.diperbaruiPada: now.toIso8601String(),\n      };\n\n      final fromSupabase = EventModel.fromSupabase('1', data);\n      expect(fromSupabase.id, event.id);\n      expect(fromSupabase.linkGambar, event.linkGambar);\n      expect(fromSupabase.statusAktif, event.statusAktif);\n      expect(fromSupabase.tanggalDibuat.year, event.tanggalDibuat.year);\n      expect(fromSupabase.tanggalDibuat.month, event.tanggalDibuat.month);\n      expect(fromSupabase.tanggalDibuat.day, event.tanggalDibuat.day);\n    });\n\n    test('04. toSupabase harus menghasilkan map yang benar', () {\n      final map = event.toSupabase();\n\n      expect(map[NamaKolom.id], '1');\n      expect(map[NamaKolom.linkGambar], 'image.png');\n      expect(map[NamaKolom.statusAktif], true);\n    });\n  });\n}\n